var H = {};

// assertBase(contentType) — 3 tests base para cualquier request
H.assertBase = function(contentType) {
    pm.test("Response is received", function () {
        pm.expect(pm.response).to.be.ok;
    });
    pm.test("Status code is 200", function () {
        pm.response.to.have.status(200);
    });
    pm.test("Media-Type is correct", function () {
        pm.response.to.have.header("Content-Type", contentType);
    });
};

// assertListMeta(response, resourcePath, uuidEnvVar, allowEmpty)
// Items present, no duplicados, links únicos, self-link, guarda UUID
H.assertListMeta = function(response, resourcePath, uuidEnvVar, allowEmpty) {
    var pepperLocation = pm.environment.get("PEPPER_LOCATION") || "";
    var items = response.items || [];

    pm.test("Items array is present" + (allowEmpty ? "" : " and not empty"), function () {
        if (allowEmpty) {
            pm.expect(response).to.have.property("items").that.is.an("array");
        } else {
            pm.expect(response).to.have.property("items").that.is.an("array").that.is.not.empty;
        }
    });

    pm.test("No duplicate names in items", function () {
        var names = items.map(function(i) { return i.name; });
        pm.expect(new Set(names).size).to.equal(names.length);
    });

    pm.test("Links are unique for each item", function () {
        var links = items.map(function(i) { return i.links.self; });
        pm.expect(new Set(links).size).to.equal(links.length);
    });

    pm.test("Self link matches expected URL", function () {
        pm.expect(response.links.self).to.equal(pepperLocation + "/" + resourcePath);
    });

    if (uuidEnvVar) {
        var firstSelf = items[0] && items[0].links && items[0].links.self;
        if (firstSelf) {
            pm.environment.set(uuidEnvVar, firstSelf);
            console.log("✔ " + uuidEnvVar + " seteado: " + firstSelf);
        } else {
            console.log("ℹ No UUID encontrado para " + uuidEnvVar + " (válido en Brasil)");
        }
    }
};

// assertItemsSendRequest(response, resourcePath)
// Itera hasta 10 items (name+links) y hace sendRequest al self link
// Para catálogos simples con solo name + links por item
H.assertItemsSendRequest = function(response, resourcePath) {
    var pepperLocation = pm.environment.get("PEPPER_LOCATION") || "";
    var authHeader = pm.environment.get("AUTH_BASIC_HEADER");
    var items = response.items || [];
    var limit = Math.min(items.length, 10);
    var escapedBase = pepperLocation.replace(/[-/\^$*+?.()|[]{}]/g, "\\$&");
    var regex = new RegExp("^" + escapedBase + "/" + resourcePath + "/[\\w-]+$");

    items.slice(0, limit).forEach(function(item, index) {
        var label = "Item " + (index + 1) + " (" + item.name + ")";

        pm.test(label + " contains expected properties", function () {
            pm.expect(item).to.include.all.keys("name", "links");
            pm.expect(item.links).to.be.an("object").that.has.property("self");
        });

        pm.test(label + " 'name' is a non-empty string", function () {
            pm.expect(item.name).to.be.a("string").that.is.not.empty;
        });

        pm.test(label + " 'self' link is a valid URL", function () {
            pm.expect(item.links.self).to.be.a("string").and.to.match(regex);
        });

        if (item.links && item.links.self) {
            pm.sendRequest({
                url: item.links.self,
                method: "GET",
                header: { Authorization: authHeader }
            }, function(err, res) {
                pm.test(label + " self link returns status 200", function () {
                    pm.expect(err).to.equal(null);
                    pm.expect(res.code).to.equal(200);
                });
            });
        } else {
            pm.test(label + " does not contain a 'self' link", function () {
                pm.expect.fail("Missing 'self' link.");
            });
        }
    });
};

// assertCatalogItem(response, uuidEnvVar)
// Verifica que el self link del item coincida con el UUID guardado en env
H.assertCatalogItem = function(response, uuidEnvVar) {
    var expected = pm.environment.get(uuidEnvVar);
    pm.test("Self link is correct", function () {
        pm.expect(response.links.self).to.equal(expected);
        console.log("Self link is correct:", expected);
    });
};

// assertSensitivity(response)
// Validaciones comunes: body no vacío, no null en campos base, results válido
H.assertSensitivity = function(response) {
    pm.test("Response body is not empty", function () {
        pm.expect(pm.response.text()).to.not.be.empty;
    });
    pm.test("No main fields are null", function () {
        ["numberOfScenarios", "step", "baseline", "results"].forEach(function(key) {
            pm.expect(response[key]).to.not.be.null;
        });
    });
    pm.test("Results array is valid", function () {
        pm.expect(response.results).to.be.an("array");
        pm.expect(response.results.length).to.equal(response.numberOfScenarios + 1);
    });
};
// assertTradableSecurityList(response)
// Validaciones comunes a los 4 endpoints de lista de Tradable Securities
H.assertTradableSecurityList = function(response) {
    pm.test("Items array is present and not empty", function () {
        pm.expect(response).to.have.property("items").that.is.an("array").that.is.not.empty;
    });
    pm.test("Each item has correct properties", function () {
        response.items.forEach(function(item) {
            pm.expect(item).to.be.an("object").that.includes.all.keys("currency", "exchange", "tradingEvery", "security", "ticker", "links");
            pm.expect(item.currency).to.be.a("string").and.to.match(/^https?:\/\/[\w.-]+\/currencies\/[\w-]+$/);
            pm.expect(item.exchange).to.be.a("string").and.to.match(/^https?:\/\/[\w.-]+\/markets\/[\w-]+$/);
            pm.expect(item.tradingEvery).to.be.a("number");
            pm.expect(item.security).to.be.an("object").that.includes.all.keys("shortName", "type", "links");
            pm.expect(item.security.shortName).to.be.a("string").and.to.not.be.empty;
            pm.expect(item.security.type).to.be.a("string").and.to.not.be.empty;
            pm.expect(item.security.links).to.be.an("object").with.property("self").that.is.a("string");
            pm.expect(item.security.links.self).to.match(/^https?:\/\/[\w.-]+\/(?:[\w-]+\/)?bonds\/[\w-]+$/);
            pm.expect(item.ticker).to.be.a("string").and.to.not.be.empty;
            pm.expect(item.links).to.be.an("object").that.includes.all.keys("self", "metrics");
            pm.expect(item.links.self).to.be.a("string").and.to.match(/^https?:\/\/[\w.-]+\/tradable-securities\/[\w-]+(?:\?.*)?$/);
            pm.expect(item.links.metrics).to.be.a("string").and.to.match(/^https?:\/\/[\w.-]+\/tradable-securities\/[\w-]+\/metrics$/);
        });
    });
    pm.test("No duplicate tickers in items", function () {
        var tickers = response.items.map(function(item) { return item.ticker; });
        pm.expect(new Set(tickers).size).to.equal(tickers.length);
    });
    pm.test("Links are unique for each tradable security", function () {
        var links = response.items.map(function(item) { return item.links.self; });
        pm.expect(new Set(links).size).to.equal(links.length);
    });
    pm.test("TradingEvery has value 100 or 1000 for each item", function () {
        response.items.forEach(function(item) {
            pm.expect(item).to.have.property("tradingEvery").to.be.oneOf([100, 1000]);
        });
    });
    pm.test("Security.type has value Bond for each item", function () {
        response.items.forEach(function(item) {
            pm.expect(item).to.have.property("security").that.is.an("object");
            pm.expect(item.security).to.have.property("type").that.equals("Bond");
        });
    });
};
